const porSku = {};
for (const item of $input.all()) {
  const j = item.json;
  const sku = String(j.item_id);
  if (!sku || sku === 'undefined') continue;
  if (!porSku[sku]) porSku[sku] = [];
  porSku[sku].push({ f: String(j.date), v: Number(j.sales) || 0 });
}
const series = {};
for (const sku of Object.keys(porSku)) {
  const arr = porSku[sku].sort((a, b) => (a.f < b.f ? -1 : 1));
  series[sku] = { ventas: arr.map(x => x.v), fechas: arr.map(x => x.f) };
}
return [{ json: { series: series } }];

const STOCK={FOODS_2_019:41,FOODS_2_197:107,FOODS_3_064:213,FOODS_3_080:225,FOODS_3_090:159,FOODS_3_099:83,FOODS_3_120:378,FOODS_3_252:465,FOODS_3_282:56,FOODS_3_295:132,FOODS_3_499:95,FOODS_3_501:283,FOODS_3_511:74,FOODS_3_555:109,FOODS_3_586:291,FOODS_3_587:420,FOODS_3_681:66,FOODS_3_714:94,FOODS_3_739:80,FOODS_3_741:183};
const d=$input.first().json;
const pron=d.pronosticos||{};
const presion=d.presion_quiebre_por_producto||{};
const todos=[];
for(const sku of Object.keys(pron)){
  const p=pron[sku];
  const demanda7=p.demanda_total;
  const dia=p.demanda_prom_dia||0;
  const stock=(STOCK[sku]!=null)?STOCK[sku]:Math.round(dia*5);
  const punto=demanda7;
  const cobertura=dia>0?Math.round((stock/dia)*10)/10:999;
  const reponer=(stock<punto);
  todos.push({item_id:sku,demanda_7d:demanda7,demanda_prom_dia:dia,stock_actual:stock,punto_reorden:Math.round(punto*10)/10,cobertura_dias:cobertura,reponer:reponer,urgente:(reponer&&cobertura<3),cantidad_sugerida:Math.max(0,Math.round(punto-stock))});
}
const aReponer=todos.filter(x=>x.reponer).sort((a,b)=>b.cantidad_sugerida-a.cantidad_sugerida);
const urgentes=todos.filter(x=>x.urgente).sort((a,b)=>a.cobertura_dias-b.cobertura_dias);
const urgentes_text=urgentes.map(u=>'- '+u.item_id+': quedan '+u.stock_actual+' uds, cobertura '+u.cobertura_dias+' dias (demanda 7d '+u.demanda_7d+')').join('\n');
const reclamos=Object.keys(presion).map(k=>k+' ('+presion[k]+')');
const prompt='Eres un analista de inventario para retail. Tienda CA_1: '+aReponer.length+' de '+todos.length+' productos requieren reposicion (lead time 7 dias). Productos a reponer: '+JSON.stringify(aReponer)+'. Reclamos de quiebre de clientes: '+JSON.stringify(reclamos)+'. Reglas: usa SOLO estos datos, no inventes; prioridad alta para mayor deficit o con reclamos, media para deficit pequeno; si un dato es dudoso revision_humana=true; se breve (1-2 frases por campo), en espanol. Responde UNICAMENTE con un JSON valido (sin texto extra, sin markdown), un item por producto a reponer, con esta estructura: {"resumen":"menciona que son '+aReponer.length+' de '+todos.length+' productos","items":[{"item_id":"","diagnostico":"","recomendacion":"","prioridad":"alta","justificacion":"","revision_humana":false}]}';
return [{json:{tienda:'CA_1',lead_time_dias:7,total_sku:todos.length,n_reponer:aReponer.length,n_urgentes:urgentes.length,items:aReponer,urgentes:urgentes,urgentes_text:urgentes_text,reclamos_quiebre:reclamos,prompt:prompt}}];

let texto = '';
try {
  const arr = $input.first().json.content || [];
  for (const c of arr) { if (c && c.type === 'text' && c.text) { texto = c.text; break; } }
} catch (e) { texto = ''; }
const limpio = String(texto).replace(/```json/gi, '').replace(/```/g, '').trim();
let out;
try { out = JSON.parse(limpio); } catch (e) { out = { resumen: limpio, items: [] }; }
out = out || {};
const items = out.items || [];
const fecha = new Date().toISOString().slice(0, 10);
const TABLERO = 'https://TU-URL-NGROK.ngrok-free.dev/tablero';
const filas = items.map(i => '<tr><td>' + i.item_id + '</td><td>' + (i.prioridad || '') + '</td><td>' + (i.recomendacion || '') + '</td><td>' + (i.justificacion || '') + '</td><td>' + (i.revision_humana ? 'Si' : 'No') + '</td></tr>').join('');
const email_html = '<h3>Reposicion integrada CA_1 (' + fecha + ')</h3><p><b>' + (out.resumen || '') + '</b></p><table border=1 cellpadding=6><tr><th>SKU</th><th>Prioridad</th><th>Recomendacion</th><th>Justificacion</th><th>Revision humana</th></tr>' + filas + '</table><p><a href=' + TABLERO + '>Ver el tablero interactivo</a></p>';
const telegram_text = 'Reposicion integrada CA_1 - ' + fecha + '\n' + (out.resumen || '') + '\n\n' + items.map(i => '- [' + (i.prioridad || '') + '] ' + i.item_id + ': ' + (i.recomendacion || '') + (i.revision_humana ? ' (revision humana)' : '')).join('\n') + '\n\nTablero en vivo: ' + TABLERO;
const n_alta = items.filter(i => i.prioridad === 'alta').length;
return [{ json: { fecha: fecha, tienda: 'CA_1', resumen: (out.resumen || ''), n_items: items.length, n_prioridad_alta: n_alta, recomendaciones: items, email_html: email_html, telegram_text: telegram_text } }];

